        "code": "import sys\r\nfrom math import gcd, isqrt\r\nfrom Crypto.Cipher import PKCS1_OAEP\r\nfrom Crypto.PublicKey import RSA\r\nimport random\r\n\r\n# Data dari output.txt\r\nn = \r\ne = 65537\r\nc = bytes.fromhex(\"\")\r\n\r\ndef primes_upto(limit):\r\n    sieve = [True] * (limit + 1)\r\n    for p in range(2, isqrt(limit) + 1):\r\n        if sieve[p]:\r\n            for i in range(p * p, limit + 1, p):\r\n                sieve[i] = False\r\n    return [p for p in range(2, limit + 1) if sieve[p]]\r\n\r\ndef ec_add(P, Q, n):\r\n    if P is None: return Q\r\n    if Q is None: return P\r\n    x1, y1 = P\r\n    x2, y2 = Q\r\n    \r\n    if x1 == x2 and y1 == y2:\r\n        num = (3 * x1 * x1) % n\r\n        den = (2 * y1) % n\r\n    elif x1 == x2:\r\n        return None\r\n    else:\r\n        num = (y2 - y1) % n\r\n        den = (x2 - x1) % n\r\n\r\n    g = gcd(den, n)\r\n    if 1 < g < n:\r\n        raise ValueError(g)  # Zero-divisor ditemukan, faktor didapatkan!\r\n    if g == n:\r\n        return None\r\n\r\n    inv_den = pow(den, -1, n)\r\n    lam = (num * inv_den) % n\r\n    x3 = (lam * lam - x1 - x2) % n\r\n    y3 = (lam * (x1 - x3) - y1) % n\r\n    return (x3, y3)\r\n\r\ndef ec_mul(P, k, n):\r\n    R = None\r\n    for bit in bin(k)[2:]:\r\n        R = ec_add(R, R, n)\r\n        if bit == '1':\r\n            R = ec_add(R, P, n)\r\n    return R\r\n\r\n# Membangun skalar K (faktor dari bilangan prima <= batas smooth)\r\nSMOOTH_BOUND = 2**15\r\nmultipliers = []\r\nfor p in primes_upto(SMOOTH_BOUND):\r\n    q = p\r\n    while q * p <= SMOOTH_BOUND:\r\n        q *= p\r\n    multipliers.append(q)\r\n\r\nprint(\"[*] Memulai eksploitasi custom ECM pada y^2 = x^3 + B ...\")\r\np_factor = None\r\nattempts = 0\r\n\r\nwhile not p_factor:\r\n    attempts += 1\r\n    # Memilih titik kurva eliptik secara acak (memilih B secara implisit)\r\n    x = random.randrange(1, n)\r\n    y = random.randrange(1, n)\r\n    P = (x, y)\r\n    print(f\"[-] Mencoba twist acak (Percobaan ke-{attempts})...\")\r\n    \r\n    try:\r\n        for q in multipliers:\r\n            P = ec_mul(P, q, n)\r\n            if P is None:\r\n                break\r\n    except ValueError as err:\r\n        p_factor = err.args[0]\r\n        print(f\"[+] JACKPOT! Faktor p ditemukan: {p_factor}\")\r\n        break\r\n\r\n# Mendekripsi RSA\r\nq_factor = n // p_factor\r\nphi = (p_factor - 1) * (q_factor - 1)\r\nd = pow(e, -1, phi)\r\n\r\nkey = RSA.construct((n, e, d, p_factor, q_factor))\r\ncipher = PKCS1_OAEP.new(key)\r\nflag = cipher.decrypt(c)\r\n\r\nprint(\"\\n[+] FLAG:\", flag.decode(errors='ignore'))"
